const int BUTTON = 2;
const int LED = 13;

int last = LOW;    // the reading from the last loop
bool lit = false;  // is the LED on? (toggle mode)

void setup() {
  pinMode(BUTTON, INPUT);  // the 10 kΩ pull-down holds D2 LOW
  pinMode(LED, OUTPUT);
}

void loop() {
  int now = digitalRead(BUTTON);
  digitalWrite(LED, now);
  last = now;
}
